source = '''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = min(Counter(value for row in grid for value in row), key=Counter(value for row in grid for value in row).get)
    for r in range(h):
        points = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
'''
